package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="obrigacao_repasse",schema="adm_eclesial") public class ObrigacaoRepasse { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="regra_repasse_id",nullable=false) Long regraRepasseId; @Column(nullable=false) LocalDate competencia; @Column(nullable=false,precision=15,scale=2) BigDecimal valorBase; @Column(nullable=false,precision=15,scale=2) BigDecimal valorExclusoes; @Column(nullable=false,precision=15,scale=2) BigDecimal valorRepasse; @Column(name="data_vencimento",nullable=false) LocalDate dataVencimento; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) StatusObrigacaoRepasse status; @Column(columnDefinition="text") String observacao; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getRegraRepasseId(){return regraRepasseId;} public LocalDate getCompetencia(){return competencia;} public BigDecimal getValorBase(){return valorBase;} public BigDecimal getValorExclusoes(){return valorExclusoes;} public BigDecimal getValorRepasse(){return valorRepasse;} public LocalDate getDataVencimento(){return dataVencimento;} public StatusObrigacaoRepasse getStatus(){return status;} public String getObservacao(){return observacao;} public void setRegraRepasseId(Long v){regraRepasseId=v;} public void setCompetencia(LocalDate v){competencia=v;} public void setValorBase(BigDecimal v){valorBase=v;} public void setValorExclusoes(BigDecimal v){valorExclusoes=v;} public void setValorRepasse(BigDecimal v){valorRepasse=v;} public void setDataVencimento(LocalDate v){dataVencimento=v;} public void setStatus(StatusObrigacaoRepasse v){status=v;} public void setObservacao(String v){observacao=v;} }